// Map an inbound WhatsApp message to the LeadPilot incoming webhook.
// Backend resolves the outreach by provider message ID, then sender number.
const m = $input.first().json;
const msg = m.messages?.[0] || m;
return [{ json: {
  from_number: msg.from || '',
  provider_message_id: msg.context?.id || msg.id || null,
  body: msg.text?.body || ''
} }];
